catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   //Type appropriate comment here, and begin script below
   g_form.setMandatory('first_payment_approver_dispaly', false);
   g_form.setMandatory('alternate_buyer', false);
   var fieldsToShowMap = {
	'0': [],
	'1': ['geo', 'country', 'company'],
	'2': ['step2_variables'],
	'3': ['step3_variables'],
	'4': ['step4_variables'],
	'5': ['requested_by', 'alternate_buyer', 'first_payment_approver_dispaly']
   };

   var fieldsToShow = fieldsToShowMap[newValue] || [];

   var allFields = [
	'geo', 'country', 'company',
	'step2_variables', 'step3_variables', 'step4_variables',
	'requested_by', 'alternate_buyer', 'first_payment_approver_dispaly'
   ];

   for (var i = 0; i < allFields.length; i++) {
	var field = allFields[i];
	g_form.setDisplay(field, fieldsToShow.indexOf(field) !== -1);
   }

   if (newValue === '5') {
	 g_form.setMandatory('alternate_buyer', true);
     g_form.setMandatory('first_payment_approver_dispaly', true);
    }
    else{
	  g_form.setMandatory('alternate_buyer', false);
   	  g_form.setMandatory('first_payment_approver_dispaly', false);
    }

}
